{
  "version": "1",
  "step_id": "current_semester_mean",
  "result_spec": {
    "metric_id": "u.grade_mean.v1",
    "shape": "aggregate",
    "group_keys": [],
    "columns": [
      {"name": "sum_units", "type": "integer", "nullable": false},
      {"name": "graded_count", "type": "integer", "nullable": false},
      {"name": "enrollment_count", "type": "integer", "nullable": false}
    ],
    "components": {
      "sum": "sum_units",
      "denominator": "graded_count",
      "count": "enrollment_count"
    },
    "unit": "grade_hundredth",
    "scale": 100
  },
  "sql": "SELECT COALESCE(SUM(e.grade_units), 0) AS sum_units, COUNT(e.grade_units) AS graded_count, COUNT(*) AS enrollment_count FROM Enrollments e JOIN Offerings o ON e.offering_id = o.offering_id WHERE o.semester_id = :semester_id",
  "parameters": [
    {
      "name": "semester_id",
      "type": "text",
      "integer_value": null,
      "text_value": "S1"
    }
  ],
  "expected_columns": ["sum_units", "graded_count", "enrollment_count"],
  "result_kind": "aggregate",
  "explanation": "Returns mean-grade components for resolved current semester S1, including all offerings and retakes. NULL grades are excluded from the sum and graded count but included in the enrollment count."
}
